      img.src = url.href;
      img.dataset.sha256 = digest;
      img.dataset.originalSrc = item.originalSrc;
      img.addEventListener('error', () => {
        if (generation !== mapSelectionGeneration) return;
        notice.textContent = '確認済みの原画PNGを表示できませんでした'; notice.hidden = false;
      });
