      notice.hidden = true;
      document.getElementById('selected-source').textContent = `検証済み原画PNG · ${item.originalSrc} · SHA-256 ${digest}`;
      const link = document.getElementById('selected-link');
      link.href = url.href; link.textContent = '原画PNGを見る ↗';
