    const link=document.getElementById('selected-link');link.href=webgpu?makeMapPreview(item).href:item.src;link.textContent=webgpu?(mapInteractionPreview?'キャラ操作fixtureを見る ↗':'WebGPUマッププレビューを見る ↗'):'原本画像を見る ↗';
